-- (2) upsert: kata HSK 3.0 masuk/pindah ke level barunya (1-4); data di-update.
--     meaning_id SENGAJA tidak ditimpa (pertahankan terjemahan Indonesia yang sudah ada).
INSERT INTO vocab (hanzi, pinyin, meaning_en, hsk_level, radical, frequency, pos, forms)
SELECT hanzi, pinyin, meaning_en, hsk_level, radical, frequency, pos, forms FROM _v30
ON CONFLICT (hanzi) DO UPDATE SET
  pinyin     = EXCLUDED.pinyin,
  meaning_en = EXCLUDED.meaning_en,
  hsk_level  = EXCLUDED.hsk_level,
  radical    = EXCLUDED.radical,
  frequency  = EXCLUDED.frequency,
  pos        = EXCLUDED.pos,
  forms      = EXCLUDED.forms;

-- (3) buang sisa kata lama di level 1-4 yang BUKAN bagian HSK 3.0 new-1..4
DELETE FROM vocab v
WHERE v.hsk_level <= 4
  AND NOT EXISTS (SELECT 1 FROM _v30 s WHERE s.hanzi = v.hanzi);

-- (4) verifikasi SESUDAH (target: L1=506, L2=750, L3=953, L4=972; L5-6 = sisa lama)
SELECT 'SESUDAH' AS tahap, hsk_level, count(*) FROM vocab GROUP BY hsk_level ORDER BY hsk_level;
SELECT count(*) AS total_vocab FROM vocab;

